function applyPublicBusinessCatalogs(state) {
	const rename = (value) => {
		if (typeof value === "string") {
			for (const [before, after] of Object.entries(publicBusinessCatalogs_default.demoAliases)) value = value.replaceAll(before, after);
			return value;
		}
		if (Array.isArray(value)) return value.map(rename);
		if (value && Object.getPrototypeOf(value) === Object.prototype) return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, rename(item)]));
		return value;
	};
	const next = rename(state);
	const meta = {
		decision_id: "DEC-134",
		rule_id: "BR-DEMO-CATALOGOS-REALES-PUBLICOS",
		test_id: "TST-DEMO-CATALOGOS-REALES-PUBLICOS",
		fictitious: false,
		source: {
			kind: "AUTHORIZED_PUBLIC_NAMES",
			asOf: publicBusinessCatalogs_default.asOf
		}
	};
	const options = (values, key) => values.map((label, index) => ({
		id: `PUBLIC-${key}-${index + 1}`,
		label,
		active: null,
		...meta
	}));
	const suppliers = options(publicBusinessCatalogs_default.suppliers, "SUPPLIER"), companies = options(publicBusinessCatalogs_default.companies, "COMPANY");
	const unconfigured = suppliers.map((item) => ({
		...item,
		company: "",
		jdeCode: "",
		shortCode: "",
		buyer: "",
		authorizedBuyers: [],
		importer: "",
		category: "",
		line: "",
		creditDays: null,
		paymentTerm: "",
		nationalizedIn: "",
		nationalizationPlace: "",
		linesPerHour: null,
		email: "",
		version: 1,
		versions: []
	}));
	return {
		...next,
		catalogs: {
			...next.catalogs,
			suppliers,
			companies
		},
		supplierMasters: [...next.supplierMasters || [], ...unconfigured],
		publicBusinessCatalogs: {
			asOf: publicBusinessCatalogs_default.asOf,
			suppliers: suppliers.length,
			companies: companies.length,
			simulation: true
		}
	};
}
