/** Re-key the sample graph, including embedded source keys; retain Blob/File objects. */
function remapDemoReferences(value, mapping) {
	const pattern = new RegExp(Object.keys(mapping).map((key) => key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|"), "g");
	const replace = (text) => text.replace(pattern, (matched) => mapping[matched]);
	if (typeof value === "string") return replace(value);
	if (Array.isArray(value)) return value.map((item) => remapDemoReferences(item, mapping));
	if (value && Object.getPrototypeOf(value) === Object.prototype) return Object.fromEntries(Object.entries(value).map(([key, item]) => [replace(key), remapDemoReferences(item, mapping)]));
	return value;
}
function reserveDemoIdentities(context, examples) {
	let working = context;
	const mapping = {}, identities = {};
	for (const exp of examples) {
		const openingDate = exp.compras?.openingDate || exp.createdAt?.slice(0, 10) || localDateKey(/* @__PURE__ */ new Date());
		const reservation = reserveExpedienteIdentity(working, {
			supplier: exp.supplier,
			company: exp.company,
			transportType: exp.transportType || exp.importaciones?.shipment?.mode,
			openingDate
		}, { at: exp.createdAt });
		if (!reservation) throw Error("La muestra requiere la configuración de nomenclatura del expediente.");
		mapping[exp.id] = reservation.id;
		identities[exp.id] = {
			...reservation.metadata,
			...DEMO_IDENTITY_META
		};
		working = {
			...working,
			expedienteIdentityConfig: reservation.config
		};
	}
	return {
		mapping,
		identities,
		config: working.expedienteIdentityConfig
	};
}
